import functools

def log_calls(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print("calling", func.__name__, args)
        result = func(*args, **kwargs)
        print("returned", result)
        return result
    return wrapper

@log_calls
def with_tax(amount, rate=0.18):
    return amount * (1 + rate)

total = with_tax(1000)
print(total, with_tax.__name__)

